package postgres
import("context";"errors";"github.com/jackc/pgx/v5";"github.com/jackc/pgx/v5/pgxpool";"github.com/google/uuid";"github.com/menerjangbadai/dashboard/internal/domain";q "github.com/menerjangbadai/dashboard/internal/adapters/postgres/sqlcgen")
type Store struct{Pool *pgxpool.Pool}
func safeErr(e error)error{if errors.Is(e,pgx.ErrNoRows){return domain.ErrNotFound};return e}
func(s *Store) Membership(ctx context.Context,a domain.Actor)(domain.Actor,error){e:=s.Pool.QueryRow(ctx,`SELECT r.role_id,m.authz_revision FROM organization_members m JOIN user_roles r USING(org_id,user_id) JOIN users u ON u.id=m.user_id JOIN organizations o ON o.id=m.org_id WHERE m.org_id=$1 AND m.user_id=$2 AND m.active AND u.active AND o.active`,a.OrgID,a.UserID).Scan(&a.Role,&a.Revision);if errors.Is(e,pgx.ErrNoRows){return a,domain.ErrForbidden};return a,e}
func(s *Store) ListBrands(ctx context.Context,a domain.Actor)([]domain.Brand,error){rows,e:=q.New(s.Pool).ListBrands(ctx,q.ListBrandsParams{OrgID:a.OrgID,UserID:a.UserID});if e!=nil{return nil,e};out:=make([]domain.Brand,0,len(rows));for _,r:=range rows{out=append(out,domain.Brand(r))};return out,nil}
func(s *Store) GetBrand(ctx context.Context,a domain.Actor,id string)(domain.Brand,error){if _,e:=uuid.Parse(id);e!=nil{return domain.Brand{},domain.ErrNotFound};r,e:=q.New(s.Pool).GetBrand(ctx,q.GetBrandParams{OrgID:a.OrgID,UserID:a.UserID,ID:id});return domain.Brand(r),safeErr(e)}
func(s *Store) CreateBrand(ctx context.Context,a domain.Actor,b domain.Brand)(domain.Brand,error){tx,e:=s.Pool.Begin(ctx);if e!=nil{return b,e};defer tx.Rollback(ctx);r,e:=q.New(tx).InsertBrand(ctx,q.InsertBrandParams{OrgID:a.OrgID,UserID:a.UserID,ID:uuid.NewString(),Name:b.Name,Description:b.Description,Website:b.Website});if e!=nil{return b,safeErr(e)};b=domain.Brand(r)
 if _,e=tx.Exec(ctx,"INSERT INTO user_brand_access(org_id,brand_id,user_id) VALUES($1,$2,$3)",a.OrgID,b.ID,a.UserID);e!=nil{return b,e};if e=audit(ctx,tx,a,"brand.created",b.ID);e!=nil{return b,e};return b,tx.Commit(ctx)}
func(s *Store) UpdateBrand(ctx context.Context,a domain.Actor,b domain.Brand)(domain.Brand,error){tx,e:=s.Pool.Begin(ctx);if e!=nil{return b,e};defer tx.Rollback(ctx);r,e:=q.New(tx).UpdateBrand(ctx,q.UpdateBrandParams{OrgID:a.OrgID,UserID:a.UserID,ID:b.ID,Name:b.Name,Description:b.Description,Website:b.Website,Status:b.Status});if e!=nil{return b,safeErr(e)};event:="brand.updated";if b.Status=="archived"{event="brand.archived"};if e=audit(ctx,tx,a,event,b.ID);e!=nil{return b,e};return domain.Brand(r),tx.Commit(ctx)}
func audit(ctx context.Context,tx pgx.Tx,a domain.Actor,event string,resource any)error{_,e:=tx.Exec(ctx,"INSERT INTO audit_logs(org_id,user_id,event,resource_id) VALUES($1,$2,$3,$4)",a.OrgID,a.UserID,event,resource);return e}
// Bootstrap explicitly provisions one exact issuer/subject into its own initial organization. Existing mappings are never promoted.
func(s *Store) Bootstrap(ctx context.Context,issuer,subject,name string)(domain.Actor,error){a:=domain.Actor{OrgID:uuid.NewString(),UserID:uuid.NewString(),Role:"owner",Revision:1};if issuer==""||subject==""||name==""{return a,domain.ErrInvalid};tx,e:=s.Pool.Begin(ctx);if e!=nil{return a,e};defer tx.Rollback(ctx)
 var exists bool;e=tx.QueryRow(ctx,"SELECT EXISTS(SELECT 1 FROM external_identities WHERE issuer=$1 AND subject=$2)",issuer,subject).Scan(&exists);if e!=nil{return a,e};if exists{return a,domain.ErrForbidden}
 for _,cmd:=range []struct{sql string;args []any}{{"INSERT INTO organizations(id,name) VALUES($1,'MenerjangBadai')",[]any{a.OrgID}},{"INSERT INTO users(id,display_name) VALUES($1,$2)",[]any{a.UserID,name}},{"INSERT INTO external_identities(issuer,subject,user_id) VALUES($1,$2,$3)",[]any{issuer,subject,a.UserID}},{"INSERT INTO organization_members(org_id,user_id) VALUES($1,$2)",[]any{a.OrgID,a.UserID}},{"INSERT INTO user_roles(org_id,user_id,role_id) VALUES($1,$2,'owner')",[]any{a.OrgID,a.UserID}}}{if _,e=tx.Exec(ctx,cmd.sql,cmd.args...);e!=nil{return a,e}}
 if e=audit(ctx,tx,a,"identity.provisioned",nil);e!=nil{return a,e};return a,tx.Commit(ctx)}
